import { useState, useEffect, useRef, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Brain, Plus, X, Save, Lightbulb, AlertCircle, Handshake, Clock } from 'lucide-react';
import { toast } from 'sonner';
import { motion } from 'framer-motion';
import { Json } from '@/integrations/supabase/types';

interface MemoryData {
  id?: string;
  // Identidade da linha carregada: usada para nunca gravar em contato alheio.
  contact_id?: string;
  facts: string[];
  objections_handled: string[];
  promises_made: string[];
  pending_items: string[];
  commercial_summary: string;
  cumulative_summary: string;
}

interface ConversationMemoryPanelProps {
  contactId: string;
  profileId?: string | null;
}

const SECTIONS = [
  { key: 'facts' as const, label: 'Fatos relevantes', icon: Lightbulb, color: 'text-primary' },
  { key: 'objections_handled' as const, label: 'Objeções tratadas', icon: AlertCircle, color: 'text-warning' },
  { key: 'promises_made' as const, label: 'Promessas feitas', icon: Handshake, color: 'text-success' },
  { key: 'pending_items' as const, label: 'Pendências', icon: Clock, color: 'text-destructive' },
];

const emptyMemory = (): MemoryData => ({
  facts: [],
  objections_handled: [],
  promises_made: [],
  pending_items: [],
  commercial_summary: '',
  cumulative_summary: '',
});

export function ConversationMemoryPanel({ contactId, profileId }: ConversationMemoryPanelProps) {
  // null = sem registro carregado para o contato atual (vazio explícito, distinto de erro).
  const [memory, setMemory] = useState<MemoryData | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [newItems, setNewItems] = useState<Record<string, string>>({});
  const isMountedRef = useRef(true);
  // Identifica a requisição corrente: resposta de um contato anterior é descartada.
  const requestIdRef = useRef(0);

  const loadMemory = useCallback(async (targetContactId: string) => {
    const requestId = ++requestIdRef.current;
    // Limpa o estado ANTES de carregar: nunca exibir dado do contato anterior.
    setMemory(null);
    setNewItems({});
    setError(null);
    setLoading(true);

    const { data, error: loadError } = await supabase
      .from('conversation_memory')
      .select('*')
      .eq('contact_id', targetContactId)
      .maybeSingle();

    // Resposta obsoleta (troca de contato/requisição mais nova): ignorar.
    if (!isMountedRef.current || requestId !== requestIdRef.current) return;

    if (loadError) {
      // Erro real: não confundir com ausência de registro.
      setError(loadError.message || 'Erro ao carregar a memória');
      setMemory(null);
    } else if (data && data.contact_id === targetContactId) {
      setError(null);
      setMemory({
        id: data.id,
        contact_id: data.contact_id,
        facts: Array.isArray(data.facts) ? (data.facts as Json[]).map(String) : [],
        objections_handled: Array.isArray(data.objections_handled) ? (data.objections_handled as Json[]).map(String) : [],
        promises_made: Array.isArray(data.promises_made) ? (data.promises_made as Json[]).map(String) : [],
        pending_items: Array.isArray(data.pending_items) ? (data.pending_items as Json[]).map(String) : [],
        commercial_summary: data.commercial_summary || '',
        cumulative_summary: data.cumulative_summary || '',
      });
    } else {
      // Sem registro para este contato: estado vazio explícito.
      setError(null);
      setMemory(null);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- fetch-on-mount/troca-de-contato padrão, sem estado derivado de props para sincronizar.
    loadMemory(contactId);
  }, [contactId, loadMemory]);

  const addItem = (key: keyof Pick<MemoryData, 'facts' | 'objections_handled' | 'promises_made' | 'pending_items'>) => {
    const value = newItems[key]?.trim();
    if (!value) return;
    setMemory(prev => {
      const base = prev ?? emptyMemory();
      return { ...base, [key]: [...base[key], value] };
    });
    setNewItems(prev => ({ ...prev, [key]: '' }));
  };

  useEffect(() => {
    isMountedRef.current = true;
    return () => { isMountedRef.current = false; };
  }, []);

  const removeItem = (key: keyof Pick<MemoryData, 'facts' | 'objections_handled' | 'promises_made' | 'pending_items'>, index: number) => {
    setMemory(prev => {
      const base = prev ?? emptyMemory();
      return { ...base, [key]: base[key].filter((_: string, i: number) => i !== index) };
    });
  };

  const saveMemory = async () => {
    const targetContactId = contactId;
    setSaving(true);
    const current = memory;
    const payload = {
      contact_id: targetContactId,
      facts: current?.facts ?? [],
      objections_handled: current?.objections_handled ?? [],
      promises_made: current?.promises_made ?? [],
      pending_items: current?.pending_items ?? [],
      commercial_summary: current?.commercial_summary || null,
      cumulative_summary: current?.cumulative_summary || null,
      updated_by: profileId,
    };

    // Só atualiza a linha se o id em estado pertence a ESTE contato; senão trata como ausência.
    const ownRowId = current?.id && current?.contact_id === targetContactId ? current.id : null;
    const { error: saveError } = ownRowId
      ? await supabase
          .from('conversation_memory')
          .update(payload)
          .eq('id', ownRowId)
          .eq('contact_id', targetContactId)
      : await supabase.from('conversation_memory').insert(payload);

    if (!saveError) {
      toast.success('Memória salva');
      loadMemory(targetContactId);
    } else {
      toast.error('Erro ao salvar');
    }
    if (isMountedRef.current) setSaving(false);
  };

  if (loading) {
    return <div className="space-y-2">{[1,2,3].map(i => <div key={i} className="h-16 bg-muted/30 rounded-lg animate-pulse" />)}</div>;
  }

  const view = memory ?? emptyMemory();

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Brain className="w-4 h-4 text-primary" />
          <span className="text-sm font-medium">Memória da Conversa</span>
        </div>
        <Button size="sm" variant="outline" className="h-7 text-xs" onClick={saveMemory} disabled={saving || !!error}>
          <Save className="w-3 h-3 mr-1" />
          {saving ? 'Salvando...' : 'Salvar'}
        </Button>
      </div>

      {error ? (
        <div role="alert" className="flex items-start gap-1.5 text-xs text-destructive bg-destructive/10 rounded px-2 py-1.5">
          <AlertCircle className="w-3.5 h-3.5 mt-0.5 shrink-0" />
          <span className="flex-1">Erro ao carregar a memória: {error}</span>
          <Button size="sm" variant="outline" className="h-6 text-3xs" onClick={() => loadMemory(contactId)}>
            Tentar novamente
          </Button>
        </div>
      ) : (
        <>
          {memory === null && (
            <p className="text-xs text-muted-foreground">Sem memória registrada para este contato.</p>
          )}

          {SECTIONS.map(({ key, label, icon: Icon, color }) => (
            <div key={key} className="space-y-1.5">
              <div className="flex items-center gap-1.5">
                <Icon className={`w-3.5 h-3.5 ${color}`} />
                <span className="text-xs font-medium text-muted-foreground">{label}</span>
                <Badge variant="outline" className="text-3xs h-4">{view[key].length}</Badge>
              </div>
              <div className="space-y-1">
                {view[key].map((item: string, idx: number) => (
                  <motion.div
                    key={idx}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="flex items-center gap-1.5 text-xs bg-muted/20 rounded px-2 py-1 group"
                  >
                    <span className="flex-1">{item}</span>
                    <button onClick={() => removeItem(key, idx)} className="opacity-0 group-hover:opacity-100">
                      <X className="w-3 h-3 text-muted-foreground hover:text-destructive" />
                    </button>
                  </motion.div>
                ))}
              </div>
              <div className="flex gap-1">
                <input
                  value={newItems[key] || ''}
                  onChange={(e) => setNewItems(prev => ({ ...prev, [key]: e.target.value }))}
                  placeholder="Adicionar..."
                  className="flex-1 text-xs bg-transparent border border-border/30 rounded px-2 py-1 focus:outline-none focus:border-primary/50"
                  onKeyDown={(e) => e.key === 'Enter' && addItem(key)}
                />
                <Button variant="ghost" size="icon" className="w-6 h-6" onClick={() => addItem(key)}>
                  <Plus className="w-3 h-3" />
                </Button>
              </div>
            </div>
          ))}

          <div className="space-y-1.5">
            <span className="text-xs font-medium text-muted-foreground">Resumo comercial</span>
            <Textarea
              value={view.commercial_summary}
              onChange={(e) => setMemory(prev => ({ ...(prev ?? emptyMemory()), commercial_summary: e.target.value }))}
              placeholder="Resumo do contexto comercial..."
              rows={2}
              className="text-xs"
            />
          </div>

          <div className="space-y-1.5">
            <span className="text-xs font-medium text-muted-foreground">Resumo cumulativo</span>
            <Textarea
              value={view.cumulative_summary}
              onChange={(e) => setMemory(prev => ({ ...(prev ?? emptyMemory()), cumulative_summary: e.target.value }))}
              placeholder="Resumo acumulado entre atendentes..."
              rows={2}
              className="text-xs"
            />
          </div>
        </>
      )}
    </div>
  );
}
